import 'package:ping_discover_network/ping_discover_network.dart';

const port = 80;
final stream = NetworkAnalyzer.discover2(
  '192.168.0', port,
  timeout: Duration(milliseconds: 5000),
);

stream.listen((NetworkAddress addr) {
  if (addr.exists) {
    print('Found device: ${addr.ip}:$port');
  }
});
